          "title": "First-Principles: Audit Spektrum Hessian, L-Smoothness & Rasio Titik Pelana",
          "language": "python",
          "filename": "05_1_hessian_curvature_saddle_audit.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(42)\nn, d = 400, 6\n# Fitur dengan skala heterogen untuk memunculkan anistropi kurvatur\nscales = np.array([1.0, 2.5, 0.4, 8.0, 0.2, 4.0])\nX = rng.normal(0.0, 1.0, size=(n, d)) * scales\nw_true = np.array([0.8, -0.5, 1.2, -0.3, 0.9, -0.6])\nlogits = X @ w_true\ny = (rng.uniform(0, 1, size=n) < 1.0 / (1.0 + np.exp(-logits))).astype(float)\n\nlam = 0.25\n\ndef loss_fn(w):\n    z = X @ w\n    # Stabilisasi log(1 + exp(z)) tanpa overflow\n    log_loss = np.mean(np.logaddexp(0.0, z) - y * z)\n    return float(log_loss + 0.5 * lam * np.dot(w, w))\n\ndef grad_fn(w):\n    p = 1.0 / (1.0 + np.exp(-np.clip(X @ w, -30, 30)))\n    return (X.T @ (p - y)) / n + lam * w\n\ndef hess_fn(w):\n    p = 1.0 / (1.0 + np.exp(-np.clip(X @ w, -30, 30)))\n    s = p * (1.0 - p)\n    return (X.T * s) @ X / n + lam * np.eye(d)\n\nw0 = np.zeros(d)\nH0 = hess_fn(w0)\neigs = np.linalg.eigvalsh(H0)\nmu_local = float(eigs[0])\nL_local = float(eigs[-1])\n# Batas global L untuk Logistic Regression: 0.25 * eig_max(X^T X / n) + lam\nL_global = float(0.25 * np.linalg.eigvalsh((X.T @ X) / n)[-1] + lam)\nkappa_global = L_global / lam\n\nprint(\"=== Audit Kurvatur Hessian Logistic Regression (L2=0.25) ===\")\nprint(f\"Eigenvalue Hessian di w=0 : min={mu_local:.4f}, max={L_local:.4f}\")\nprint(f\"Batas Global (mu, L)      : mu={lam:.4f}, L={L_global:.4f}\")\nprint(f\"Condition Number Global   : kappa = L / mu = {kappa_global:.2f}\")\n\n# Verifikasi empiris ketaksamaan L-smoothness & mu-strong convexity pada 200 pasangan titik\nsmooth_ok, strong_ok = 0, 0\nfor _ in range(200):\n    u = rng.normal(0, 0.5, size=d)\n    v = rng.normal(0, 0.5, size=d)\n    diff = v - u\n    sq_norm = float(np.dot(diff, diff))\n    lhs = loss_fn(v) - loss_fn(u) - float(np.dot(grad_fn(u), diff))\n    if lhs <= 0.5 * L_global * sq_norm + 1e-10:\n        smooth_ok += 1\n    if lhs >= 0.5 * lam * sq_norm - 1e-10:\n        strong_ok += 1\n\nprint(f\"Verifikasi L-Smoothness   : {smooth_ok}/200 pasangan lolos\")\nprint(f\"Verifikasi Strong Convex  : {strong_ok}/200 pasangan lolos\")\n\n# Ilustrasi eksponensialnya titik pelana (saddle points) pada matriks Hessian acak dimensi d\nprint(\"--- Peluang Titik Stasioner Non-Konveks Menjadi Lokal Minimum (GOE Random Hessian) ---\")\nfor dim in (2, 6, 12, 20):\n    min_count = 0\n    trials = 600\n    for _ in range(trials):\n        A = rng.normal(0, 1, size=(dim, dim))\n        H_rand = 0.5 * (A + A.T)\n        if np.all(np.linalg.eigvalsh(H_rand) > 0):\n            min_count += 1\n    print(f\"Dimensi d={dim:2d} -> fraksi strict local min: {min_count/trials:.4f} (saddle/max: {1 - min_count/trials:.4f})\")",
          "expectedOutput": "=== Audit Kurvatur Hessian Logistic Regression (L2=0.25) ===\nEigenvalue Hessian di w=0 : min=0.2591, max=16.0742\nBatas Global (mu, L)      : mu=0.2500, L=16.0742\nCondition Number Global   : kappa = L / mu = 64.30\nVerifikasi L-Smoothness   : 200/200 pasangan lolos\nVerifikasi Strong Convex  : 200/200 pasangan lolos\n--- Peluang Titik Stasioner Non-Konveks Menjadi Lokal Minimum (GOE Random Hessian) ---\nDimensi d= 2 -> fraksi strict local min: 0.1267 (saddle/max: 0.8733)\nDimensi d= 6 -> fraksi strict local min: 0.0000 (saddle/max: 1.0000)\nDimensi d=12 -> fraksi strict local min: 0.0000 (saddle/max: 1.0000)\nDimensi d=20 -> fraksi strict local min: 0.0000 (saddle/max: 1.0000)",
          "actualOutput": "=== Audit Kurvatur Hessian Logistic Regression (L2=0.25) ===\nEigenvalue Hessian di w=0 : min=0.2591, max=16.0742\nBatas Global (mu, L)      : mu=0.2500, L=16.0742\nCondition Number Global   : kappa = L / mu = 64.30\nVerifikasi L-Smoothness   : 200/200 pasangan lolos\nVerifikasi Strong Convex  : 200/200 pasangan lolos\n--- Peluang Titik Stasioner Non-Konveks Menjadi Lokal Minimum (GOE Random Hessian) ---\nDimensi d= 2 -> fraksi strict local min: 0.1267 (saddle/max: 0.8733)\nDimensi d= 6 -> fraksi strict local min: 0.0000 (saddle/max: 1.0000)\nDimensi d=12 -> fraksi strict local min: 0.0000 (saddle/max: 1.0000)\nDimensi d=20 -> fraksi strict local min: 0.0000 (saddle/max: 1.0000)",
