          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.svm import SVC\n\nX, y_bin = make_classification(\n    n_samples=240, n_features=4, n_informative=3, n_redundant=0,\n    class_sep=1.1, random_state=42\n)\nX = StandardScaler().fit_transform(X)\ny = np.where(y_bin == 1, 1.0, -1.0)\n\nC = 1.5\nsvm = SVC(kernel=\"linear\", C=C, tol=1e-7).fit(X, y)\nw = svm.coef_[0]\nb = float(svm.intercept_[0])\nmargins = y * (X @ w + b)\n\n# Ambil alpha_i untuk semua sampel (0 untuk non-SV)\nalphas = np.zeros(len(y))\nalphas[svm.support_] = np.abs(svm.dual_coef_[0])\n\n# Klasifikasikan titik berdasarkan 3 rezim KKT Complementary Slackness SVM\nfree_sv = (alphas > 1e-4) & (alphas < C - 1e-4)\nbound_sv = alphas >= C - 1e-4\nnon_sv = alphas <= 1e-4\n\n# Bandingkan Nilai Objektif Primal vs Dual SVM secara eksak\nxi = np.maximum(0.0, 1.0 - margins)\nprimal_val = 0.5 * np.dot(w, w) + C * np.sum(xi)\nK = (X * y[:, None]) @ (X * y[:, None]).T\ndual_val = np.sum(alphas) - 0.5 * (alphas @ K @ alphas)\n\nprint(\"=== Audit KKT & Duality Gap pada Soft-Margin Linear SVM (C=1.5) ===\")\nprint(f\"Non-SV (alpha=0)     : {int(non_sv.sum()):3d} sampel | min margin = {margins[non_sv].min():.4f} (>= 1.0)\")\nprint(f\"Free SV (0<alpha<C)  : {int(free_sv.sum()):3d} sampel | max |margin-1| = {np.max(np.abs(margins[free_sv] - 1.0)):.2e}\")\nprint(f\"Bound SV (alpha=C)   : {int(bound_sv.sum()):3d} sampel | max margin = {margins[bound_sv].max():.4f} (<= 1.0)\")\nprint(f\"Primal Obj = {primal_val:.6f} | Dual Obj = {dual_val:.6f} | Gap = {abs(primal_val - dual_val):.3e}\")\n\n# Audit Inersia Hessian pada permukaan non-konveks f(x, y) = x^3 - 3x + y^2 - 2y\ndef hess_nonconvex(x_val):\n    return np.array([[6.0 * x_val, 0.0], [0.0, 2.0]])\n\nprint(\"--- Klasifikasi Titik Stasioner Non-Konveks f(x,y) = x^3 - 3x + y^2 - 2y ---\")\nfor name, x_pt in [(\"Titik A (x=+1, y=1)\", 1.0), (\"Titik B (x=-1, y=1)\", -1.0)]:\n    ev = np.linalg.eigvalsh(hess_nonconvex(x_pt))\n    kind = \"Local Minimum (PD)\" if np.all(ev > 0) else \"Saddle Point (Indefinite)\"\n    print(f\"{name} -> eigenvalues={ev.tolist()} -> {kind}\")",
