          "code": "import numpy as np\n\n# Fungsi kuadratik strongly convex ill-conditioned: f(w) = 0.5 * w^T Q w\n# L = 200.0, mu = 1.0 -> condition number kappa = 200\nL, mu = 200.0, 1.0\nkappa = L / mu\nQ = np.array([L, mu])\nw_init = np.array([4.0, 4.0])\n\ndef f_val(w):\n    return float(0.5 * np.sum(Q * (w ** 2)))\n\ndef grad(w):\n    return Q * w\n\ndef run_gd(max_iter=2000, tol=1e-6):\n    w = w_init.copy()\n    eta = 1.0 / L  # langkah aman standar 1/L\n    for t in range(1, max_iter + 1):\n        w = w - eta * grad(w)\n        if f_val(w) <= tol:\n            return t, f_val(w)\n    return max_iter, f_val(w)\n\ndef run_polyak(max_iter=2000, tol=1e-6):\n    w = w_init.copy()\n    v = np.zeros_like(w)\n    # Parameter optimal Polyak Heavy-Ball untuk kuadratik\n    eta = 4.0 / ((np.sqrt(L) + np.sqrt(mu)) ** 2)\n    beta = ((np.sqrt(L) - np.sqrt(mu)) / (np.sqrt(L) + np.sqrt(mu))) ** 2\n    for t in range(1, max_iter + 1):\n        v = beta * v - eta * grad(w)\n        w = w + v\n        if f_val(w) <= tol:\n            return t, f_val(w)\n    return max_iter, f_val(w)\n\ndef run_nag(max_iter=2000, tol=1e-6):\n    w = w_init.copy()\n    y = w.copy()\n    eta = 1.0 / L\n    beta = (np.sqrt(kappa) - 1.0) / (np.sqrt(kappa) + 1.0)\n    for t in range(1, max_iter + 1):\n        w_next = y - eta * grad(y)\n        y = w_next + beta * (w_next - w)\n        w = w_next\n        if f_val(w) <= tol:\n            return t, f_val(w)\n    return max_iter, f_val(w)\n\nt_gd, f_gd = run_gd()\nt_hb, f_hb = run_polyak()\nt_nag, f_nag = run_nag()\n\nprint(f\"=== Benchmark Konvergensi Lembah Ill-Conditioned (kappa={kappa:.0f}, tol=1e-6) ===\")\nprint(f\"Gradient Descent (eta=1/L)        : {t_gd:4d} iter | f(w)={f_gd:.3e}\")\nprint(f\"Nesterov Accelerated Grad (NAG)   : {t_nag:4d} iter | f(w)={f_nag:.3e}\")\nprint(f\"Polyak Heavy-Ball (Optimal Quad)  : {t_hb:4d} iter | f(w)={f_hb:.3e}\")\nprint(f\"Percepatan NAG vs GD Murni        : {t_gd / t_nag:.2f}x lebih sedikit iterasi\")\nprint(f\"Rasio Teoretis sqrt(kappa)        : {np.sqrt(kappa):.2f}x\")",
