          "code": "import numpy as np\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(7)\nn, d = 1024, 5\nscales = np.array([1e-2, 1.0, 50.0, 2000.0, 1e5])\nX_raw = rng.normal(0.0, 1.0, size=(n, d)) * scales\nX_std = StandardScaler().fit_transform(X_raw)\n\n# Audit Condition Number matriks Hessian (1/n) X^T X sebelum vs sesudah scaling\neig_raw = np.linalg.eigvalsh((X_raw.T @ X_raw) / n)\neig_std = np.linalg.eigvalsh((X_std.T @ X_std) / n)\nkappa_raw = eig_raw[-1] / eig_raw[0]\nkappa_std = eig_std[-1] / eig_std[0]\n\nprint(\"=== Audit Condition Number Sebelum vs Sesudah StandardScaler ===\")\nprint(f\"Condition Number Raw    (kappa_raw) : {kappa_raw:.3e}\")\nprint(f\"Condition Number Scaled (kappa_std) : {kappa_std:.4f}\")\nprint(f\"Faktor Reduksi kappa                : {kappa_raw / kappa_std:.3e}x\")\n\n# Audit Noise Ball Mini-Batch SGD: f(w) = (1/(2n)) ||X_std w - y||^2\nw_true = np.array([1.5, -2.0, 0.8, 1.2, -0.7])\ny = X_std @ w_true + rng.normal(0.0, 0.5, size=n)\nw_ols = np.linalg.lstsq(X_std, y, rcond=None)[0]\nf_opt = float(0.5 * np.mean((X_std @ w_ols - y) ** 2))\n\nprint(\"--- Varians Gradien & Steady-State Noise Ball Mini-Batch SGD (eta=0.05 tetap) ---\")\nfor batch_size in (8, 32, 128, 512):\n    # Ukur varians gradien stokastik pada w_ols\n    grads = []\n    for _ in range(150):\n        idx = rng.choice(n, size=batch_size, replace=False)\n        g = (X_std[idx].T @ (X_std[idx] @ w_ols - y[idx])) / batch_size\n        grads.append(np.dot(g, g))\n    grad_var = float(np.mean(grads))\n\n    # Jalankan 400 update SGD dengan eta konstan=0.05 dan ukur residual rata-rata 50 langkah terakhir\n    w = np.zeros(d)\n    tail_gaps = []\n    for step in range(400):\n        idx = rng.choice(n, size=batch_size, replace=False)\n        g = (X_std[idx].T @ (X_std[idx] @ w - y[idx])) / batch_size\n        w = w - 0.05 * g\n        if step >= 350:\n            tail_gaps.append(float(0.5 * np.mean((X_std @ w - y) ** 2)) - f_opt)\n    print(f\"Batch B={batch_size:3d} | E[||g_B||^2] di w* = {grad_var:.5f} | Noise-Ball Gap = {np.mean(tail_gaps):.5f}\")",
