          "code": "import numpy as np\n\n# 1. Audit Bias Correction pada momen awal Adam (beta1=0.9, beta2=0.999)\nbeta1, beta2, eps = 0.9, 0.999, 1e-8\nprint(\"=== Faktor Koreksi Bias Adam: 1/(1 - beta^t) ===\")\nfor t in (1, 5, 20, 100, 1000):\n    c1 = 1.0 / (1.0 - beta1 ** t)\n    c2 = 1.0 / (1.0 - beta2 ** t)\n    print(f\"t={t:4d} | 1/(1-beta1^t)={c1:7.3f} | 1/(1-beta2^t)={c2:8.3f}\")\n\n# 2. Bukti Kuantitatif: Adam + L2-in-Gradient vs AdamW (Decoupled Weight Decay)\n# Masalah kuadratik stokastik f(w) = 0.5*||w - w_star||^2 dengan w_star = [4.0, 4.0],\n# namun koordinat 0 memiliki noise gradien besar (sigma=30.0) sedangkan koordinat 1 kecil (sigma=0.2).\ndef run_optimizer(mode: str, steps: int = 800, lr: float = 0.02, wd: float = 0.5):\n    rng = np.random.default_rng(42)\n    w = np.array([4.0, 4.0], dtype=float)\n    w_star = np.array([4.0, 4.0], dtype=float)\n    m = np.zeros(2)\n    v = np.zeros(2)\n    noise_scales = np.array([30.0, 0.2])\n    for t in range(1, steps + 1):\n        # Gradien stokastik tak bias dari data loss 0.5 * ||w - w_star||^2\n        g = (w - w_star) + rng.normal(0.0, noise_scales)\n        if mode == \"adam_l2\":\n            g = g + wd * w  # BUG: L2 ikut terbagi oleh sqrt(v_hat) -> coord 0 kebal regularisasi!\n        m = beta1 * m + (1.0 - beta1) * g\n        v = beta2 * v + (1.0 - beta2) * (g ** 2)\n        m_hat = m / (1.0 - beta1 ** t)\n        v_hat = v / (1.0 - beta2 ** t)\n        if mode == \"adamw\":\n            w = w * (1.0 - lr * wd)  # Decoupled weight decay menyusutkan w secara seragam\n        w = w - lr * m_hat / (np.sqrt(v_hat) + eps)\n    return w, np.sqrt(v_hat)\n\nw_l2, rms_l2 = run_optimizer(\"adam_l2\")\nw_aw, rms_aw = run_optimizer(\"adamw\")\n\nprint(\"--- Penyusutan Bobot (w_star=[4.0, 4.0], wd=0.5, noise_std=[30.0, 0.2]) ---\")\nprint(f\"Adam + L2-in-Grad -> w={np.round(w_l2, 4).tolist()} | sqrt(v_hat)={np.round(rms_l2, 2).tolist()}\")\nprint(f\"AdamW Decoupled   -> w={np.round(w_aw, 4).tolist()} | sqrt(v_hat)={np.round(rms_aw, 2).tolist()}\")\nprint(f\"Penyusutan Coord-0 (gradien bising) -> Adam+L2: {4.0 - w_l2[0]:.4f} vs AdamW: {4.0 - w_aw[0]:.4f}\")",
