          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.metrics import log_loss\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.preprocessing import StandardScaler\n\nX, y = make_classification(\n    n_samples=1000, n_features=20, n_informative=12, n_redundant=4,\n    flip_y=0.04, random_state=42\n)\nX_tr, X_val, y_tr, y_val = train_test_split(X, y, test_size=0.25, stratify=y, random_state=42)\nscaler = StandardScaler().fit(X_tr)\nX_tr_s, X_val_s = scaler.transform(X_tr), scaler.transform(X_val)\n\n# Bagian A: Scikit-Learn MLPClassifier dengan Adam pada variasi alpha (L2)\nprint(\"=== Scikit-Learn MLPClassifier (solver='adam') ===\")\nfor alpha in (1e-4, 1e-1):\n    mlp = MLPClassifier(\n        hidden_layer_sizes=(32, 16), solver=\"adam\", alpha=alpha,\n        learning_rate_init=0.01, max_iter=120, random_state=42\n    ).fit(X_tr_s, y_tr)\n    p_val = mlp.predict_proba(X_val_s)[:, 1]\n    print(f\"MLP Adam (alpha={alpha:<6}) -> Val LogLoss={log_loss(y_val, p_val):.4f} | iter={mlp.n_iter_}\")\n\n# Bagian B: Benchmark LR Schedule (Constant vs Linear Warmup + Cosine Annealing) dengan AdamW\ndef lr_schedule(step: int, total_steps: int, base_lr: float, mode: str) -> float:\n    if mode == \"constant\":\n        return base_lr\n    warmup = max(1, int(0.10 * total_steps))\n    if step <= warmup:\n        return base_lr * (step / warmup)\n    progress = (step - warmup) / max(1, total_steps - warmup)\n    return base_lr * (0.05 + 0.95 * 0.5 * (1.0 + np.cos(np.pi * progress)))\n\ndef train_logreg_adamw(schedule_mode: str, total_steps: int = 240, base_lr: float = 0.08, wd: float = 0.05):\n    rng = np.random.default_rng(123)\n    w = np.zeros(X_tr_s.shape[1])\n    b = 0.0\n    mw, vw = np.zeros_like(w), np.zeros_like(w)\n    mb, vb = 0.0, 0.0\n    b1, b2, eps = 0.9, 0.999, 1e-8\n    batch_size = 64\n    for step in range(1, total_steps + 1):\n        idx = rng.choice(len(X_tr_s), size=batch_size, replace=False)\n        xb, yb = X_tr_s[idx], y_tr[idx]\n        p = 1.0 / (1.0 + np.exp(-np.clip(xb @ w + b, -30, 30)))\n        gw = (xb.T @ (p - yb)) / batch_size\n        gb = float(np.mean(p - yb))\n        lr = lr_schedule(step, total_steps, base_lr, schedule_mode)\n        mw = b1 * mw + (1 - b1) * gw\n        vw = b2 * vw + (1 - b2) * (gw ** 2)\n        mb = b1 * mb + (1 - b1) * gb\n        vb = b2 * vb + (1 - b2) * (gb ** 2)\n        w = w * (1.0 - lr * wd) - lr * (mw / (1 - b1 ** step)) / (np.sqrt(vw / (1 - b2 ** step)) + eps)\n        b = b - lr * (mb / (1 - b1 ** step)) / (np.sqrt(vb / (1 - b2 ** step)) + eps)\n    p_val = 1.0 / (1.0 + np.exp(-np.clip(X_val_s @ w + b, -30, 30)))\n    return float(log_loss(y_val, p_val)), float(np.linalg.norm(w))\n\nprint(\"--- Benchmark LR Schedule pada AdamW (240 langkah mini-batch) ---\")\nfor mode in (\"constant\", \"warmup_cosine\"):\n    val_ll, w_norm = train_logreg_adamw(mode)\n    print(f\"Schedule={mode:<14} -> Val LogLoss={val_ll:.4f} | ||w||_2={w_norm:.4f}\")",
          "expectedOutput": "=== Scikit-Learn MLPClassifier (solver='adam') ===\nMLP Adam (alpha=0.0001) -> Val LogLoss=0.8663 | iter=86\nMLP Adam (alpha=0.1   ) -> Val LogLoss=0.6659 | iter=120\n--- Benchmark LR Schedule pada AdamW (240 langkah mini-batch) ---\nSchedule=constant       -> Val LogLoss=0.4695 | ||w||_2=2.0553\nSchedule=warmup_cosine  -> Val LogLoss=0.4404 | ||w||_2=2.1256",
          "actualOutput": "=== Scikit-Learn MLPClassifier (solver='adam') ===\nMLP Adam (alpha=0.0001) -> Val LogLoss=0.8663 | iter=86\nMLP Adam (alpha=0.1   ) -> Val LogLoss=0.6659 | iter=120\n--- Benchmark LR Schedule pada AdamW (240 langkah mini-batch) ---\nSchedule=constant       -> Val LogLoss=0.4695 | ||w||_2=2.0553\nSchedule=warmup_cosine  -> Val LogLoss=0.4404 | ||w||_2=2.1256",
