          "id": "code-ml-05-4-ch05_4_scratch",
          "title": "First-Principles: Benchmark ISTA vs FISTA vs Cyclic Coordinate Descent",
          "language": "python",
          "filename": "05_4_ista_fista_coordinate_descent.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(42)\nn, d = 300, 40\n# Buat matriks fitur berkorelasi sedang (AR1 rho=0.7) agar kecepatan solver terlihat jelas\ncov = 0.7 ** np.abs(np.arange(d)[:, None] - np.arange(d)[None, :])\nX = rng.multivariate_normal(np.zeros(d), cov, size=n)\nX = (X - X.mean(axis=0)) / X.std(axis=0)\nw_true = np.zeros(d)\nw_true[:6] = np.array([2.5, -1.8, 1.4, -1.1, 0.9, -0.7])\ny = X @ w_true + rng.normal(0.0, 0.5, size=n)\ny = y - y.mean()\n\nlam = 0.15\nL = float(np.linalg.eigvalsh((X.T @ X) / n)[-1])\neta = 1.0 / L\n\ndef soft_threshold(z, tau):\n    return np.sign(z) * np.maximum(np.abs(z) - tau, 0.0)\n\ndef lasso_obj(w):\n    r = X @ w - y\n    return float(0.5 * np.mean(r ** 2) + lam * np.sum(np.abs(w)))\n\n# Referensi optimum presisi tinggi via Coordinate Descent 400 sweep\nw_ref = np.zeros(d)\nr_ref = y.copy()\ncol_sq = np.sum(X ** 2, axis=0) / n\nfor _ in range(400):\n    for j in range(d):\n        w_old = w_ref[j]\n        r_ref += X[:, j] * w_old\n        rho = float(np.dot(X[:, j], r_ref) / n)\n        w_new = float(soft_threshold(rho, lam) / col_sq[j])\n        w_ref[j] = w_new\n        r_ref -= X[:, j] * w_new\nf_star = lasso_obj(w_ref)\ntol = 1e-6\n\n# 1. ISTA (Proximal Gradient — O(1/t))\nw_ista = np.zeros(d)\nit_ista = 1500\nfor it in range(1, 1501):\n    g = (X.T @ (X @ w_ista - y)) / n\n    w_ista = soft_threshold(w_ista - eta * g, eta * lam)\n    if lasso_obj(w_ista) - f_star <= tol:\n        it_ista = it\n        break\n\n# 2. FISTA (Accelerated Proximal Gradient — O(1/t^2))\nw_fista = np.zeros(d)\nz_fista = np.zeros(d)\nt_k = 1.0\nit_fista = 1500\nfor it in range(1, 1501):\n    g = (X.T @ (X @ z_fista - y)) / n\n    w_next = soft_threshold(z_fista - eta * g, eta * lam)\n    t_next = 0.5 * (1.0 + np.sqrt(1.0 + 4.0 * t_k ** 2))\n    z_fista = w_next + ((t_k - 1.0) / t_next) * (w_next - w_fista)\n    w_fista, t_k = w_next, t_next\n    if lasso_obj(w_fista) - f_star <= tol:\n        it_fista = it\n        break\n\n# 3. Cyclic Coordinate Descent (tanpa tuning step size!)\nw_cd = np.zeros(d)\nr_cd = y.copy()\nit_cd = 1500\nfor sw in range(1, 1501):\n    for j in range(d):\n        w_old = w_cd[j]\n        r_cd += X[:, j] * w_old\n        rho = float(np.dot(X[:, j], r_cd) / n)\n        w_new = float(soft_threshold(rho, lam) / col_sq[j])\n        w_cd[j] = w_new\n        r_cd -= X[:, j] * w_new\n    if lasso_obj(w_cd) - f_star <= tol:\n        it_cd = sw\n        break\n\nprint(\"=== Benchmark Lasso Berkorelasi (n=300, d=40, rho=0.7, tol=1e-6) ===\")\nfor name, w_hat, steps in [\n    (\"ISTA (Proximal GD)\", w_ista, it_ista),\n    (\"FISTA (Accelerated)\", w_fista, it_fista),\n    (\"Coordinate Descent\", w_cd, it_cd),\n]:\n    n_zeros = int(np.sum(w_hat == 0.0))\n    print(f\"{name:<20} | Iter={steps:4d} | Obj={lasso_obj(w_hat):.6f} | Exact Zeros={n_zeros:2d}/{d}\")\nprint(f\"Percepatan FISTA vs ISTA : {it_ista / it_fista:.2f}x | CD vs ISTA : {it_ista / it_cd:.2f}x\")",
          "expectedOutput": "=== Benchmark Lasso Berkorelasi (n=300, d=40, rho=0.7, tol=1e-6) ===\nISTA (Proximal GD)   | Iter= 178 | Obj=1.041958 | Exact Zeros=34/40\nFISTA (Accelerated)  | Iter=  87 | Obj=1.041958 | Exact Zeros=34/40\nCoordinate Descent   | Iter=  15 | Obj=1.041957 | Exact Zeros=34/40\nPercepatan FISTA vs ISTA : 2.05x | CD vs ISTA : 11.87x",
          "actualOutput": "=== Benchmark Lasso Berkorelasi (n=300, d=40, rho=0.7, tol=1e-6) ===\nISTA (Proximal GD)   | Iter= 178 | Obj=1.041958 | Exact Zeros=34/40\nFISTA (Accelerated)  | Iter=  87 | Obj=1.041958 | Exact Zeros=34/40\nCoordinate Descent   | Iter=  15 | Obj=1.041957 | Exact Zeros=34/40\nPercepatan FISTA vs ISTA : 2.05x | CD vs ISTA : 11.87x",
          "explanation": "Mengimplementasikan soft-thresholding, ISTA, FISTA, dan Coordinate Descent dari nol untuk Lasso serta membandingkan objektif dan exact zero count.",
