          "code": "import numpy as np\nfrom scipy.optimize import minimize\nfrom sklearn.linear_model import Lasso, LogisticRegression\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(42)\nn, d = 500, 120\nX = StandardScaler().fit_transform(rng.normal(0.0, 1.0, size=(n, d)))\nw_true = np.zeros(d)\ntrue_support = np.arange(10)\nw_true[true_support] = np.array([2.2, -1.9, 1.6, -1.4, 1.2, -1.1, 0.9, -0.8, 0.7, -0.6])\ny_reg = X @ w_true + rng.normal(0.0, 0.6, size=n)\ny_cls = (1.0 / (1.0 + np.exp(-(X @ w_true))) > 0.5).astype(int)\n\n# 1. Scikit-Learn Lasso (Coordinate Descent internal berkecepatan Cython)\nlasso = Lasso(alpha=0.12, max_iter=2000, tol=1e-7).fit(X, y_reg)\nest_support = set(np.where(np.abs(lasso.coef_) > 1e-8)[0])\ntrue_set = set(true_support.tolist())\ntp = len(est_support & true_set)\nprec = tp / max(1, len(est_support))\nrec = tp / len(true_set)\n\n# 2. Logistic Regression dengan L-BFGS (smooth L2) via Scikit-Learn & SciPy L-BFGS-B\nclf_lbfgs = LogisticRegression(C=1.0, solver=\"lbfgs\", max_iter=500).fit(X, y_cls)\n\n# Bandingkan dengan SciPy L-BFGS-B eksplisit pada objektif Ridge smooth\nlam = 1.0 / n\nres_lbfgs = minimize(\n    lambda w: 0.5 * np.mean((X @ w - y_reg) ** 2) + 0.5 * lam * np.dot(w, w),\n    np.zeros(d),\n    jac=lambda w: (X.T @ (X @ w - y_reg)) / n + lam * w,\n    method=\"L-BFGS-B\",\n    options={\"maxcor\": 10, \"ftol\": 1e-12},\n)\n\nprint(\"=== Benchmark Solver Modern (n=500, d=120, 10 fitur sinyal) ===\")\nprint(f\"Lasso (Coordinate Descent) -> Exact Zeros={int(np.sum(lasso.coef_ == 0.0)):3d}/{d} | Support Prec={prec:.2f}, Rec={rec:.2f} | iter={lasso.n_iter_}\")\nprint(f\"LogisticReg (L-BFGS, L2)   -> Exact Zeros={int(np.sum(clf_lbfgs.coef_[0] == 0.0)):3d}/{d} | Acc={clf_lbfgs.score(X, y_cls):.4f} | iter={clf_lbfgs.n_iter_[0]}\")\nprint(f\"SciPy L-BFGS-B (m=10)      -> Success={res_lbfgs.success} | iter={res_lbfgs.nit} | ||grad||={np.linalg.norm(res_lbfgs.jac):.2e}\")",
          "expectedOutput": "=== Benchmark Solver Modern (n=500, d=120, 10 fitur sinyal) ===\nLasso (Coordinate Descent) -> Exact Zeros=110/120 | Support Prec=1.00, Rec=1.00 | iter=7\nLogisticReg (L-BFGS, L2)   -> Exact Zeros=  0/120 | Acc=1.0000 | iter=15\nSciPy L-BFGS-B (m=10)      -> Success=True | iter=15 | ||grad||=2.48e-05",
