          "code": "import numpy as np\n\n# Audit 1: Jejak Memori RAM (FP64 = 8 byte) Full Newton Hessian O(d^2) vs L-BFGS O(2md)\nprint(\"=== Audit Memori RAM: Full Newton Hessian O(d^2) vs L-BFGS O(2*m*d), m=10 (FP64) ===\")\nm = 10\nfor d in (100, 1_000, 10_000, 100_000, 1_000_000):\n    newton_mb = (d * d * 8) / (1024 ** 2)\n    lbfgs_mb = (2 * m * d * 8) / (1024 ** 2)\n    print(f\"d={d:9,d} | Newton Hessian={newton_mb:12.2f} MB | L-BFGS(m=10)={lbfgs_mb:8.3f} MB\")\n\n# Audit 2: Mengapa Subgradient Descent gagal menghasilkan Exact Zeros dibanding Proximal ISTA\nrng = np.random.default_rng(7)\nn, d = 200, 20\nX = rng.normal(0.0, 1.0, size=(n, d))\nw_true = np.zeros(d)\nw_true[:3] = [2.0, -1.5, 1.0]\ny = X @ w_true + rng.normal(0.0, 0.3, size=n)\n\nlam = 0.2\nL = float(np.linalg.eigvalsh((X.T @ X) / n)[-1])\neta = 0.5 / L\n\n# A. Naive Subgradient Descent (tidak pernah memotong tepat ke 0.0!)\nw_sub = np.zeros(d)\nfor t in range(1, 401):\n    g_smooth = (X.T @ (X @ w_sub - y)) / n\n    g_l1 = lam * np.sign(w_sub)\n    w_sub = w_sub - (eta / np.sqrt(t)) * (g_smooth + g_l1)\n\n# B. Proximal Gradient (ISTA dengan Soft-Thresholding)\nw_prox = np.zeros(d)\nfor _ in range(400):\n    g_smooth = (X.T @ (X @ w_prox - y)) / n\n    z = w_prox - (1.0 / L) * g_smooth\n    w_prox = np.sign(z) * np.maximum(np.abs(z) - lam / L, 0.0)\n\nprint(\"--- Sparsity Audit: Naive Subgradient vs Proximal Soft-Thresholding (17 fitur noise) ---\")\nprint(f\"Subgradient Descent -> Exact Zeros={int(np.sum(w_sub == 0.0)):2d}/20 | max |w_noise|={np.max(np.abs(w_sub[3:])):.5f}\")\nprint(f\"Proximal ISTA       -> Exact Zeros={int(np.sum(w_prox == 0.0)):2d}/20 | max |w_noise|={np.max(np.abs(w_prox[3:])):.5f}\")",
